1	export type Customer = {
2	  yearsWithMHPCO: number;
3	  previousContracts: number;
4	};
5	
6	export type Item = {
7	  type: string;
8	  material?: string;
9	  enchantment?: number;
10	  cursed?: boolean;
11	};
12	
13	const PROCESSING_FEE = 5;
14	
15	// The MHPCO price list. The spec gives each item type an insurance value and
16	// a base premium together, so they live in one table: the set of known item
17	// types is a single fact, and the two columns cannot drift apart.
18	type PriceListEntry = {
19	  insuranceValue: number;
20	  basePremium: number;
21	};
22	
23	const PRICE_LIST: Record<string, PriceListEntry> = {
24	  sword: { insuranceValue: 1000, basePremium: 100 },
25	  amulet: { insuranceValue: 600, basePremium: 60 },
26	  staff: { insuranceValue: 800, basePremium: 80 },
27	  potion: { insuranceValue: 400, basePremium: 40 },
28	  rune: { insuranceValue: 250, basePremium: 25 },
29	  moonstone: { insuranceValue: 250, basePremium: 25 },
30	};
31	
32	const CURSED_SURCHARGE_RATE = 0.5;
33	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
34	const HIGH_ENCHANTMENT_THRESHOLD = 5;
35	
36	const isKnownItemType = (item: Item): boolean => item.type in PRICE_LIST;
37	
38	const rejectUnknownItemTypes = (items: Item[]): void => {
39	  const unknown = items.find((item) => !isKnownItemType(item));
40	  if (unknown) {
41	    throw new Error(`Unknown item type: ${unknown.type}`);
42	  }
43	};
44	
45	const basePremiumOf = (item: Item): number =>
46	  PRICE_LIST[item.type].basePremium;
47	
48	const insuranceValueOf = (item: Item): number =>
49	  PRICE_LIST[item.type].insuranceValue;
50	
51	const surchargeRateOf = (item: Item): number =>
52	  (item.cursed ? CURSED_SURCHARGE_RATE : 0) +
53	  ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD
54	    ? HIGH_ENCHANTMENT_SURCHARGE_RATE
55	    : 0);
56	
57	const surchargeOf = (item: Item): number =>
58	  basePremiumOf(item) * surchargeRateOf(item);
59	
60	const sumBasePremiums = (items: Item[]): number =>
61	  items.reduce((sum, item) => sum + basePremiumOf(item), 0);
62	
63	const sumItemSurcharges = (items: Item[]): number =>
64	  items.reduce((sum, item) => sum + surchargeOf(item), 0);
65	
66	// Policy-level modifiers are whole percentages of the policy base premium.
67	// Applying them as `amount * percent / 100` keeps the arithmetic exact:
68	// `100 * 110 / 100` is 110, whereas `100 * 1.1` is 110.00000000000001.
69	const applyPercentage = (amount: number, percent: number): number =>
70	  (amount * percent) / 100;
71	
72	const FIRST_INSURANCE_SURCHARGE_PERCENTAGE = 10;
73	const LOYALTY_DISCOUNT_PERCENTAGE = 20;
74	const LOYALTY_YEARS_THRESHOLD = 2;
75	
76	const loyaltyDiscountPercentageOf = (customer: Customer): number =>
77	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD
78	    ? LOYALTY_DISCOUNT_PERCENTAGE
79	    : 0;
80	
81	const FOLLOW_UP_DISCOUNT_PERCENTAGE = 15;
82	const FOLLOW_UP_CONTRACTS_THRESHOLD = 1;
83	
84	const followUpDiscountPercentageOf = (customer: Customer): number =>
85	  customer.previousContracts >= FOLLOW_UP_CONTRACTS_THRESHOLD
86	    ? FOLLOW_UP_DISCOUNT_PERCENTAGE
87	    : 0;
88	
89	const policyPercentageDeltaOf = (customer: Customer): number =>
90	  FIRST_INSURANCE_SURCHARGE_PERCENTAGE -
91	  loyaltyDiscountPercentageOf(customer) -
92	  followUpDiscountPercentageOf(customer);
93	
94	const BLOCK_SIZE = 3;
95	const BLOCK_BASE_PREMIUM = 60;
96	
97	const isComponentBlock = (sameTypeGroup: Item[]): boolean =>
98	  sameTypeGroup.length === BLOCK_SIZE;
99	
100	const groupByType = (items: Item[]): Item[][] => {
101	  const groups = new Map<string, Item[]>();
102	  for (const item of items) {
103	    const group = groups.get(item.type) ?? [];
104	    group.push(item);
105	    groups.set(item.type, group);
106	  }
107	  return [...groups.values()];
108	};
109	
110	const basePremiumOfGroup = (sameTypeGroup: Item[]): number =>
111	  isComponentBlock(sameTypeGroup)
112	    ? BLOCK_BASE_PREMIUM
113	    : sumBasePremiums(sameTypeGroup);
114	
115	const policyBasePremiumOf = (items: Item[]): number =>
116	  groupByType(items).reduce((sum, group) => sum + basePremiumOfGroup(group), 0);
117	
118	export const quote = (customer: Customer, items: Item[]): number => {
119	  rejectUnknownItemTypes(items);
120	
121	  const policyBasePremium = policyBasePremiumOf(items);
122	  const policyPercentageAdjustment = applyPercentage(
123	    policyBasePremium,
124	    policyPercentageDeltaOf(customer),
125	  );
126	
127	  return Math.ceil(
128	    policyBasePremium +
129	      sumItemSurcharges(items) +
130	      policyPercentageAdjustment +
131	      PROCESSING_FEE,
132	  );
133	};
134	
135	export type Damage = {
136	  itemType: string;
137	  amount: number;
138	};
139	
140	export type Incident = {
141	  cause: string;
142	  damages: Damage[];
143	};
144	
145	export type ClaimResult = {
146	  payout: number;
147	  remainingCap: number;
148	};
149	
150	export const insuranceSum = (items: Item[]): number =>
151	  items.reduce((sum, item) => sum + insuranceValueOf(item), 0);
152	
153	const DEDUCTIBLE = 100;
154	
155	// Each damage entry carries its own deductible, so reimbursement is decided
156	// per entry and only then summed into the policy-level total.
157	const reimbursementFor = (damage: Damage): number => damage.amount - DEDUCTIBLE;
158	
159	const sumReimbursements = (damages: Damage[]): number =>
160	  damages.reduce((sum, damage) => sum + reimbursementFor(damage), 0);
161	
162	export const claim = (
163	  _items: Item[],
164	  incident: Incident,
165	  remainingCap: number,
166	): ClaimResult => {
167	  const reimbursementBeforeCap = sumReimbursements(incident.damages);
168	  const payout = Math.min(reimbursementBeforeCap, remainingCap);
169	  return { payout, remainingCap: remainingCap - payout };
170	};
